TR_NOTE = "Bu metin, Hollandaca asıl metnin çevirisidir. Tereddüt halinde Hollandaca metin geçerlidir."

def main_html(lang, h1, eyebrow, blocks, date, note=None):
    r = "../"
    body = "".join(f"<h2>{e(t)}</h2>{p}" for t, p in blocks)
    upd = ("Laatst bijgewerkt: " if lang == "nl" else "Son güncelleme: ") + date
    top = f'<p class="field-hint">{e(upd)}' + (f" {e(note)}" if note else "") + "</p>"
    home = "Home" if lang == "nl" else "Ana sayfa"
    return (f'<main id="main">\n  <section class="page-hero page-hero--plain"><div class="container page-hero-inner"><div class="breadcrumbs"><ol><li><a href="{r}">{home}</a></li><li>{e(h1)}</li></ol></div><p class="eyebrow">{e(eyebrow)}</p><h1>{e(h1)}</h1></div></section>\n'
            f'  <section class="section"><div class="container-narrow">{top}{body}</div></section>\n</main>')

def put(path, main, title, desc):
    s = rd(path); s = re.sub(r"<main.*?</main>", lambda m: main, s, count=1, flags=re.S)
    s = re.sub(r"<title>.*?</title>", f"<title>{e(title)}</title>", s, count=1)
    s = re.sub(r'(<meta name="description" content=")[^"]*', lambda m: m.group(1) + e(desc), s, count=1)
    s = re.sub(r'(<meta property="og:description" content=")[^"]*', lambda m: m.group(1) + e(desc), s, count=1)
    wr(path, s)

